const validServices=["","ipstack","maxmind"];const dropdown=document.getElementById("settings-geolocation-service");window.updateGeolocationService=function(){const newService=dropdown.value;if(-1===validServices.indexOf(newService)){console.log("Invalid service specified.");return}const settings={ipstack:document.getElementById("settings-ipstack"),maxmind:document.getElementById("settings-maxmind")};settings["ipstack"].style.display="none";settings["maxmind"].style.display="none";if(newService){settings[newService].style.display="block"}};